operations.curl:
curl \
  --request POST \
  --header "Authorization: Bearer ${TOKEN}" \
  --header 'Accept: application/json' \
  --header 'Content-Type: application/json' \
  --data-raw '{
  "description": "Token for CI/CD pipeline",
  "label": "My organization token",
  "resources": [
    {
      "path": "myorg/myrepo",
      "scopes": [
        "scope-image-pull"
      ],
      "type": "TYPE_REPO"
    }
  ]
}' \
  'https://hub.docker.com/v2/orgs/{name}/access-tokens'

curl \
  --request PUT \
  --header "Authorization: Bearer ${TOKEN}" \
  --header 'Accept: application/json' \
  --header 'Content-Type: application/json' \
  --data-raw '{
  "restricted_images": {
    "allow_official_images": true,
    "allow_verified_publishers": true,
    "enabled": true
  }
}' \
  'https://hub.docker.com/v2/orgs/<NAME>/settings'

curl \
  --request PATCH \
  --header "Authorization: Bearer ${TOKEN}" \
  --header 'Accept: application/json' \
  --header 'Content-Type: application/json' \
  --data-raw '{
  "description": "Token for CI/CD pipeline",
  "is_active": true,
  "label": "My organization token",
  "resources": [
    {
      "path": "myorg/myrepo",
      "scopes": [
        "scope-image-pull"
      ],
      "type": "TYPE_REPO"
    }
  ]
}' \
  'https://hub.docker.com/v2/orgs/myorganization/access-tokens/a7a5ef25-8889-43a0-8cc7-f2a94268e861'

